namespace BlazorApp.Models;

public class EquipmentItem
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using BlazorApp.Models;

namespace BlazorApp.Services;

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database delay
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 10) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 4, 22) },
            new() { Id = 3, Name = "Hydraulic Press C", Location = "Shop Floor",   LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 4, Name = "CNC Mill D",        Location = "Machine Shop", LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 5, Name = "Welding Robot E",   Location = "Assembly Line", LastInspected = new DateTime(2026, 6, 20) },
            new() { Id = 6, Name = "Compressor F",      Location = "Utility Room", LastInspected = new DateTime(2026, 2, 28) },
            new() { Id = 7, Name = "Overhead Crane G",  Location = "Warehouse 1", LastInspected = new DateTime(2026, 5, 5) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using BlazorApp.Models
@using BlazorApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        // If state was persisted during prerender, reuse it (no second service call).
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>("equipment", out var restored))
        {
            _items = restored;
        }
        else
        {
            // First render (prerender) — fetch from service.
            _items = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

